{
  "root_causes": [
    {
      "service": "ts-train-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p, span_name, count(*) n, approx_quantile(d, 0.95) p95_ms FROM (SELECT 'norm' p, span_name, duration/1e6 d FROM normal_traces WHERE service_name='ts-train-service' UNION ALL SELECT 'abn', span_name, duration/1e6 FROM abnormal_traces WHERE service_name='ts-train-service') GROUP BY 1,2 ORDER BY 2,1",
          "claim": "Train-service DB spans (SELECT ts.train_type, SELECT TrainType) rose from about 1-2 ms p95 to about 7 s p95, while the server-side spans rose in step."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration/1e6, 0.95) p95_ms FROM abnormal_traces WHERE service_name='ts-train-service' AND attr_span_kind='Client' GROUP BY 1,2,3",
          "claim": "In the incident window, train-service client DB spans run at about 7 s p95, with no error status on them."
        },
        {
          "kind": "metric",
          "sql": "SELECT p, metric, round(avg(value),3) v FROM (SELECT 'abn' p, * FROM abnormal_metrics UNION ALL SELECT 'norm', * FROM normal_metrics) WHERE service_name='ts-train-service' AND metric IN ('container.cpu.usage','container.memory.working_set','jvm.cpu.recent_utilization') GROUP BY 1,2 ORDER BY 2,1",
          "claim": "Train-service container CPU, memory and JVM CPU stay flat between normal and abnormal periods, so the slowdown is not resource saturation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-train-service",
      "to": "ts-basic-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, c.service_name AS callee, count(*) n, approx_quantile(c.duration/1e6, 0.95) callee_p95_ms, approx_quantile(p.duration/1e6, 0.95) caller_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.service_name <> p.service_name AND c.attr_span_kind='Server' GROUP BY 1,2 ORDER BY caller_p95_ms DESC",
          "claim": "ts-basic-service calls to ts-train-service show about 8.3 s p95 callee time, and basic's caller spans match it."
        }
      ]
    },
    {
      "from": "ts-basic-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, c.service_name AS callee, count(*) n, approx_quantile(c.duration/1e6, 0.95) callee_p95_ms, approx_quantile(p.duration/1e6, 0.95) caller_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.service_name <> p.service_name AND c.attr_span_kind='Server' GROUP BY 1,2 ORDER BY caller_p95_ms DESC",
          "claim": "ts-travel-service's calls to ts-basic-service take about 27.7 s p95 in the abnormal window."
        }
      ]
    },
    {
      "from": "ts-basic-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, c.service_name AS callee, count(*) n, approx_quantile(c.duration/1e6, 0.95) callee_p95_ms, approx_quantile(p.duration/1e6, 0.95) caller_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.service_name <> p.service_name AND c.attr_span_kind='Server' GROUP BY 1,2 ORDER BY caller_p95_ms DESC",
          "claim": "ts-travel2-service calls to ts-basic-service take about 8.2 s p95 in the abnormal window."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
